// CSD_RATIONALE_BEGIN
// The previous strategy relied on opportunistically opening constrained spans,
// which can fail format evaluation because math answers require arithmetic steps
// consistently wrapped in << >>. This revision makes delimiter production much
// more aggressive and regular: when outside a constrained span, it preferentially
// opens one immediately at the start and again after ordinary explanatory text,
// so the model is repeatedly steered to emit arithmetic computations inside spans.
// Inside a constrained span, it uses strict constrained decoding and closes as
// soon as the arithmetic fragment is complete, avoiding invalid or unterminated
// spans that would hurt syntax/format scores. The loop is also simplified to
// avoid rollback-heavy behavior and to keep one unit of progress per iteration,
// which helps preserve the length and cost bounds while producing well-formed
// alternating text / <<arithmetic>> structure.
// CSD_RATIONALE_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps := 0;
var preferOpen := false;

if !insideConstrainedOut {
  if |generated| == 0 {
    preferOpen := true;
  } else {
    preferOpen := true;
  }
}

