      generated := openedGenerated;
      insideConstrainedOut := openedInside;
      currentConstrainedOut := openedCurrent;
      preferOpen := false;
      steps := steps + 1;
    } else {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      if next == eosToken {
        steps := maxSteps;
      } else {
        generated := generated + [next];
        steps := steps + 1;
        if next == "." || next == "," || next == ":" || next == "=" || next == "is" || next == "are" {
          preferOpen := true;
        } else {
          if Contains(next, "step") || Contains(next, "first") || Contains(next, "then") || Contains(next, "next") || Contains(next, "so") || Contains(next, "therefore") || Contains(next, "calculate") || Contains(next, "compute") {
